public class BitSetterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("setBit(0, 0)", 1, BitSetter.setBit(0, 0));
        check("setBit(0, 3)", 8, BitSetter.setBit(0, 3));
        check("setBit(5, 1)", 7, BitSetter.setBit(5, 1));
        check("setBit(8, 3) already set", 8, BitSetter.setBit(8, 3));
        check("setBit(0, 31) sign bit", Integer.MIN_VALUE, BitSetter.setBit(0, 31));
        check("clearBit(7, 1)", 5, BitSetter.clearBit(7, 1));
        check("clearBit(8, 3)", 0, BitSetter.clearBit(8, 3));
        check("clearBit(5, 1) already clear", 5, BitSetter.clearBit(5, 1));
        check("clearBit(-1, 0)", -2, BitSetter.clearBit(-1, 0));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

